// Custom alert (Anomaly Detection app): adapters real error %.
// Analyzer: static threshold | condition: ABOVE | threshold: 5 | violating samples: 3 | sliding window: 5
//           dealerting samples: 5 | alert on missing data: off
// % of adapter responses that are neither 2xx nor 412 (412 = business answer). Minutes with 10 or fewer
// responses read as 0 so one failure on a quiet minute can't fire it.
// Lines whose HTTPCODE can't be parsed are left out instead of counted as errors.
fetch logs
| filter startsWith(aws.log_group, "/aws/ecs/srv/") and endsWith(aws.log_group, "-adapter")
| filter contains(content, "::AUDIT::RESP::")
| parse content, "LD '::HTTPCODE::' SPACE? INT:code"
| filter isNotNull(code)
| makeTimeseries total = count(default: 0),
    errors = countIf(not (code >= 200 and code < 300) and code != 412, default: 0),
    interval: 1m
| fieldsAdd error_pct = if(total[] > 10, 100.0 * errors[] / total[], else: 0.0)
| fieldsKeep timeframe, interval, error_pct

// Custom alert (Anomaly Detection app): adapters backend timeouts (504).
// Analyzer: static threshold | condition: ABOVE | threshold: 2 | violating samples: 3 | sliding window: 5
//           dealerting samples: 5 | alert on missing data: off
// Backend timeouts (HttpCode 504) reported by the adapters' GenericExceptionMapper. Fires when
// 3 of 5 minutes have 3 or more.
fetch logs
| filter startsWith(aws.log_group, "/aws/ecs/srv/") and endsWith(aws.log_group, "-adapter")
| filter contains(content, "GenericExceptionMapper") and contains(content, "HttpCode::")
| parse content, "LD 'HttpCode::' SPACE? INT:http_code"
| filter http_code == 504
| makeTimeseries timeouts = count(default: 0), interval: 1m

// Custom alert (Anomaly Detection app): adapters mapping errors.
// Analyzer: static threshold | condition: ABOVE | threshold: 2 | violating samples: 3 | sliding window: 5
//           dealerting samples: 5 | alert on missing data: off
// GenericExceptionMapper lines in the adapters, 504 timeouts excluded (those go to adapters-timeouts).
// Fires when 3 of 5 minutes have 3 or more.
fetch logs
| filter startsWith(aws.log_group, "/aws/ecs/srv/") and endsWith(aws.log_group, "-adapter")
| filter contains(content, "GenericExceptionMapper") and contains(content, "HttpCode::")
| parse content, "LD 'HttpCode::' SPACE? INT:http_code"
| filter http_code != 504
| makeTimeseries mapping_errors = count(default: 0), interval: 1m

// Custom alert (Anomaly Detection app): adapters backend 5xx.
// Analyzer: static threshold | condition: ABOVE | threshold: 1 | violating samples: 3 | sliding window: 5
//           dealerting samples: 5 | alert on missing data: off
// Adapter responses with HTTP 5xx from the backend, per minute. Fires when 3 of
// 5 minutes have 2 or more.
fetch logs
| filter startsWith(aws.log_group, "/aws/ecs/srv/") and endsWith(aws.log_group, "-adapter")
| filter contains(content, "::AUDIT::RESP::")
| parse content, "LD '::HTTPCODE::' SPACE? INT:code"
| filter code >= 500 and code < 600
| makeTimeseries backend_5xx = count(default: 0), interval: 1m

// Custom alert (Anomaly Detection app): channel rejection % (caracterAceptacion M).
// Analyzer: static threshold | condition: ABOVE | threshold: 40 | violating samples: 3 | sliding window: 5
//           dealerting samples: 5 | alert on missing data: off
// % of SOAP responses to the channel with caracterAceptacion M. M mixes business answers and technical errors,
// so 40 is a placeholder: calibrate it with the "% rechazo al canal (M)" widget, or use the seasonal baseline
// analyzer once there is history. Minutes with 10 or fewer responses read as 0.
fetch logs
| filter startsWith(aws.log_group, "/aws/ecs/srv/") and endsWith(aws.log_group, "-mngr")
| filter contains(content, "<caracterAceptacion>")
| makeTimeseries total = count(default: 0),
    rejected = countIf(contains(content, "<caracterAceptacion>M</caracterAceptacion>"), default: 0),
    interval: 1m
| fieldsAdd rejection_pct = if(total[] > 10, 100.0 * rejected[] / total[], else: 0.0)
| fieldsKeep timeframe, interval, rejection_pct

// Custom alert (Anomaly Detection app): mngr errors.
// Analyzer: static threshold | condition: ABOVE | threshold: 4 | violating samples: 3 | sliding window: 5
//           dealerting samples: 5 | alert on missing data: off
// "[ERROR" lines in the ws mngr. Fires when 3 of 5 minutes have 5 or more.
// Its normal level is not 0: if it fires too often, switch to the auto-adaptive analyzer.
fetch logs
| filter startsWith(aws.log_group, "/aws/ecs/srv/") and endsWith(aws.log_group, "-mngr")
| filter contains(content, "[ERROR")
| makeTimeseries mngr_errors = count(default: 0), interval: 1m

// Custom alert (Anomaly Detection app): end-to-end transaction latency, measured in the mngr
// (the API Gateway logs are not ingested in Dynatrace).
// Analyzer: static threshold | condition: ABOVE | threshold: 2500 | violating samples: 3 | sliding window: 5
//           dealerting samples: 5 | alert on missing data: off
// p90 of the per-transaction time (sum of the mngr ESB step times, same as total_ms in
// dynatrace/queries/trx_latency.dql), by the minute the transaction started. Minutes with 10 or fewer
// transactions read as 0. Transactions cut at the edge of the query window add up fewer steps and read faster.
// When it fires, dynatrace/queries/trx_latency.dql or slow_transactions.sh show which transactions were slow.
fetch logs
| filter startsWith(aws.log_group, "/aws/ecs/srv/") and endsWith(aws.log_group, "-mngr")
| filter contains(content, "[/")
// mngr step line: ... [trace] [rquid][canal][/ESBService/<Service>:<version>][backend][nivel][fase][paso][tiempo unidad]
| parse content, "LD '] [' LD:rquid ']['"
| fieldsAdd parts = arrayReverse(splitString(trim(content), "["))
| fieldsAdd step = replaceString(parts[1], "]", ""), step_time = replaceString(parts[0], "]", "")
| filter step != "AuditLog"
| parse step_time, "DOUBLE:step_ms"
| filter isNotNull(rquid) and isNotNull(step_ms)
| summarize total_ms = sum(step_ms), started = min(timestamp), by: { rquid }
| makeTimeseries trx = count(default: 0), p90_ms = percentile(total_ms, 90), time: started, interval: 1m
| fieldsAdd p90_ms = if(trx[] > 10, p90_ms[], else: 0.0)
| fieldsKeep timeframe, interval, p90_ms

timeseries tx = sum(custom.nexus.log.adapter.responses, default: 0), by: { cluster }, interval: 5m
| join [
    timeseries mismatches = sum(custom.nexus.log.mngr.consumer_mismatch, default: 0), by: { cluster }, interval: 5m
  ], on: { cluster }, fields: { mismatches }
| fieldsAdd per_100_tx = if(tx[] > 50, 100.0 * mismatches[] / tx[], else: 0.0)
| fieldsKeep timeframe, interval, cluster, per_100_tx
